import timefrom Sengo1 import *from mpython import *from machine import UARTuart1 = UART(1, baudrate=115200, tx=Pin.P14, rx=Pin.P13)sengo1 = Sengo1(0x60)# 自定义函数def UART():  global my_variable, key_AB, key_A, key_B, param_set, id, num, ready  sengo1.begin(uart1)def I2C():  global my_variable, key_AB, key_A, key_B, param_set, id, num, ready  sengo1.begin(i2c)def Param_Set():  global my_variable, key_AB, key_A, key_B, param_set, id, num, ready  if (param_set == 1):    param_set = 0    oled.fill_rect(0, (2-1)*16, 128, 16, 0)    oled.show()    if (key_A == 1):      key_A = 0      ready = 0      while not ((ready == 1)):        if ((sengo1.GetValue(sengo1_vision_e.kVisionFace, sentry_obj_info_e.kStatus)) > 0):          if ((sengo1.GetValue(sengo1_vision_e.kVisionFace,sentry_obj_info_e.kHeightValue)) > 50):            ready = 1          else:            oled.DispChar("Pls get close", 0, (2-1)*16, 1)            oled.show()        else:          oled.DispChar("Nobody", 0, (2-1)*16, 1)          oled.show()      sengo1.SetParam(sengo1_vision_e.kVisionFace,[0, 0, 0, 0, 100],id)      time.sleep(5)      id = (id + 1)      if (id > 10):        id = 1    if (key_B == 1):      key_B = 0      id = (id - 1)      if (1 > id):        id = 10      sengo1.SetParam(sengo1_vision_e.kVisionFace,[0, 0, 0, 0, 0],id)      time.sleep(2)    oled.fill_rect(96,0,32,16,0)    oled.show()    oled.DispChar((str(id)), 96, 0, 1)    oled.DispChar("Operation OK!", 0, (2-1)*16, 1)    oled.show()    time.sleep(0.5)    oled.fill_rect(0, (2-1)*16, 128, 16, 0)    oled.show()def Display():  global my_variable, key_AB, key_A, key_B, param_set, id, num, ready  if (param_set == 0):    oled.fill_rect(0, (2-1)*16, 128, 16, 0)    oled.show()    # Sengo1不主动返回检测识别结果，需要主控板发送指令进行读取。读取的流程：首先读取识别结果的数量，接收到指令后，Sengo1会刷新结果数据，如果结果数量不为零，那么主控再发送指令读取结果的相关信息。请务必按此流程构建程序。    # Sengo最多输出1个识别结果。    if ((sengo1.GetValue(sengo1_vision_e.kVisionFace, sentry_obj_info_e.kStatus)) > 0):      # 当与人脸的距离不超过一定范围，才输出人脸的相关信息，避免误识别      if ((sengo1.GetValue(sengo1_vision_e.kVisionFace,sentry_obj_info_e.kHeightValue)) > 50):        if ((sengo1.GetValue(sengo1_vision_e.kVisionFace,sentry_obj_info_e.kLabel)) == 0):          oled.DispChar("Stranger!", 0, (2-1)*16, 1)        else:          oled.DispChar((str("l=") + str((str((sengo1.GetValue(sengo1_vision_e.kVisionFace,sentry_obj_info_e.kLabel)))))), 0, (2-1)*16, 1)        oled.DispChar((str((sengo1.GetValue(sengo1_vision_e.kVisionFace,sentry_obj_info_e.kXValue)))), 32, 32, 1)        oled.DispChar((str((sengo1.GetValue(sengo1_vision_e.kVisionFace,sentry_obj_info_e.kYValue)))), 96, 32, 1)        oled.DispChar((str((sengo1.GetValue(sengo1_vision_e.kVisionFace,sentry_obj_info_e.kWidthValue)))), 32, 48, 1)        oled.DispChar((str((sengo1.GetValue(sengo1_vision_e.kVisionFace,sentry_obj_info_e.kHeightValue)))), 96, 48, 1)    else:      oled.fill_rect(32,32,32,16,0)      oled.fill_rect(96,32,32,16,0)      oled.fill_rect(32,48,32,16,0)      oled.fill_rect(96,48,32,16,0)    oled.show()# 事件回调函数def on_button_a_down(_):  time.sleep_ms(10)  if button_a.value() == 1: return  global param_set  global key_A  param_set = 1  key_A = 1def on_button_b_down(_):  time.sleep_ms(10)  if button_b.value() == 1: return  global param_set  global key_B  param_set = 1  key_B = 1button_a.irq(trigger=Pin.IRQ_FALLING, handler=on_button_a_down)button_b.irq(trigger=Pin.IRQ_FALLING, handler=on_button_b_down)key_A = 0key_B = 0param_set = 0ready = 0num = 0id = 1# 等待Sengo1完成初始化，此延时不可以去掉，避免Sengo1初始化尚未完成，主控板已经发送指令time.sleep(2)I2C()# 1、Sengo1的人脸识别算法可以存储并识别10张人脸，对应的label值：1-10；# 2、陌生人人脸的label值为0；# 3、可以通过摇杆进行人脸的学习以及数据删除，也可以参照本程序用代码进行实现；# 4、人脸识别算法的常见应用：门禁系统；智能家居；智能交通灯# 参考应用案例# https://www.bilibili.com/video/BV1ok4y157jV/?spm_id_from=333.1387.upload.video_card.click&vd_source=a6a4a13d17ed26ee248472534a8ec3cc# 5、Sengo1每次只能运行一种识别算法；# 6、通常情况下应当由主控板发送指令控制Sengo1算法的开启与关闭，而不是通过Sengo1的摇杆进行操作；sengo1.VisionBegin(sengo1_vision_e.kVisionFace)oled.DispChar("Algo: Face", 0, 0, 1)oled.DispChar("ID: ", 64, 0, 1)oled.DispChar((str(id)), 96, 0, 1)oled.DispChar("x=", 0, 32, 1)oled.DispChar("y=", 64, 32, 1)oled.DispChar("w=", 0, 48, 1)oled.DispChar("h=", 64, 48, 1)oled.show()while True:  Param_Set()  Display()